# Simple regex-based loader from the session file
def load_from_session():
    import os, re
    session_dir = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    sessions_file = os.path.join(session_dir, '..', '..') + '/sessions/' + os.path.basename(session_dir) + '.jsonl'

    grids = {}
    try:
        with open(sessions_file) as f:
            content = f.read()

        # Find demo pair patterns
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):.*?(\d+ \d+ \d+.*?\n(?=\d+ \d+ \d+.*?\n|$))'

        for match in re.finditer(pattern, content, re.DOTALL):
            key, h, w = match.group(1), int(match.group(2)), int(match.group(3))
            content_start = match.end()
            cells = []
            for line in content[content_start:content_start+h].strip().split('\n')[:h]:
                if line:
                    cells.append([int(x) for x in line.split()])

            if cells:
                # Determine if input or output based on key
                is_input = 'input' in key.lower()
                grids[cells] = ('input' if is_input else 'output', key)
    except Exception as e:
        print(f"Error: {e}")

    return grids

