def transform(grid):
    """Transform grid: each 3 creates a crystal pattern."""
    if not grid:
        return grid

    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    result = [[0]*width for _ in range(height)]

    # Mark each 3's position
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 3:
                # Apply crystal
                for dr in range(-2, 3):
                    for dc in range(-2, 3):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if dr == -2:
                                result[nr][nc] = 5  # top row of crystal
                            elif dr == -1:
                                if dc == 0:
                                    result[nr][nc] = 5  # 5 at center
                                elif dc in (-1, 1):
                                    result[nr][nc] = 2
                            elif dr == 0:
                                if dc == 0:
                                    result[nr][nc] = 3
                                elif dc in (-1, 1):
                                    result[nr][nc] = 2
                            elif dr == 1:
                                if dc in (-1, 1):
                                    result[nr][nc] = 2
                            elif dr == 2:
                                result[nr][nc] = 8

    # Extend band rows (r+2) with 2s beyond crystal width
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 3:
                band_row = r + 2
                if 0 <= band_row < height:
                    for nc in range(width):
                        if nc < c - 2 or nc > c + 2:
                            result[band_row][nc] = 2

    return result

