    result = [[0]*width for _ in range(height)]

    # Mark each 3's position
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 3:
                # Crystal spans cols c-3 to c+1 (5 columns)
                for dr in range(-2, 3):
                    # Crystal rows are at r-2, r-1, r, r+1, r+2
                    for dc in range(-3, 2):  # c-3 to c+1
                        nc = c + dc
                        if 0 <= nc < width:
                            nr = r + dr
                            if 0 <= nr < height:
                                if dr == -2:
                                    result[nr][nc] = 5  # top row
                                elif dr == -1:
                                    if dc == -1:
                                        result[nr][nc] = 2
                                    elif dc == 0:
                                        result[nr][nc] = 5
                                elif dr == 0:
                                    if dc == -1:
                                        result[nr][nc] = 2
                                    elif dc == 0:
                                        result[nr][nc] = 3
                                    elif dc == 1:
                                        result[nr][nc] = 2
                                elif dr == 1:
                                    if dc in (-1, 1):
                                        result[nr][nc] = 2
                                elif dr == 2:
                                    result[nr][nc] = 8

    # Extend band rows with 2s beyond crystal width
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 3:
                band_row = r + 2
                if 0 <= band_row < height:
                    # Fill columns outside c-3 to c+1 with 2s
                    for nc in range(width):
                        if nc < c - 3 or nc > c + 1:
                            result[band_row][nc] = 2

    return result

